#include <iostream>
#include <string>
#include <sstream>

std::string markdownToHtml(const std::string& markdown) {
    // Convert markdown to HTML using a markdown library
    std::string html;
    std::ostringstream oss;
    oss << markdown;
    html = oss.str();

    return html;
}

int main() {
    std::string markdown = "# Sample Markdown\n\nThis is a sample markdown text.";
    std::string html = markdownToHtml(markdown);
    std::cout << html << std::endl;
    return 0;
}
```

